            _repository = repository;
            _cache = cache;
        }

        #region ILogActionService Members

        public LogAction GetById(int? actionId)
        {
            if (actionId.HasValue)
            {
                var logAction = GetHashLogActionData()[actionId] as LogAction;

                return logAction;
            }

            return null;
        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="actionId"></param>
        /// <param name="languageCode"></param>
        /// <returns></returns>
        public string GetLogActionName(int? actionId, LanguageCode languageCode)
        {
            string actionName = string.Empty;

            if (!actionId.HasValue)
                return actionName;

            var logAction = GetById(actionId);
            if (!ReferenceEquals(logAction, null))
            {
                switch (languageCode)
                {
                    case LanguageCode.CH:
                        actionName = logAction.ActionNameCH;
                        break;
                    case LanguageCode.CS:
                        actionName = logAction.ActionNameCS;
                        break;
                    case LanguageCode.EN:
                        actionName = logAction.ActionNameEN;
                        break;
                    case LanguageCode.IT:
                        actionName = logAction.ActionNameIT;
                        break;
                    case LanguageCode.JP:
                        actionName = logAction.ActionNameJP;
                        break;
                    case LanguageCode.KO:
                        actionName = logAction.ActionNameKO;
                        break;
                    case LanguageCode.TH:
                        actionName = logAction.ActionNameTH;
                        break;
                    case LanguageCode.VI:
                        actionName = logAction.ActionNameVI;
                        break;
                }
            }

            return actionName;
        }

        /// <summary>
        /// 
