        /// <summary>
        /// 
        /// </summary>
        /// <param name="keyword"></param>
        /// <param name="languageCode"></param>
        /// <param name="actionTypeId"></param>
        /// <returns></returns>
        public List<LogAction> Search(string keyword, LanguageCode languageCode, int actionTypeId)
        {
            List<LogAction> actionList = GetLogActionList();

            if (!string.IsNullOrEmpty(keyword))
            {
                actionList = actionList.AsQueryable()
                     .Select(action => action)
                     .Where(action =>
                                        (action.ActionTypeID == actionTypeId || actionTypeId == -1) &&

                                        (
                                            (!string.IsNullOrEmpty(action.SPName)
                                                && action.SPName.ToLower().Equals(keyword.ToLower(), StringComparison.OrdinalIgnoreCase)) ||
                                            (languageCode == LanguageCode.CH && Utility.IsMatch(action.ActionNameCH, keyword)) ||
                                            (languageCode == LanguageCode.CS && Utility.IsMatch(action.ActionNameCS, keyword)) ||
                                            (languageCode == LanguageCode.EN && Utility.IsMatch(action.ActionNameEN, keyword)) ||
                                            (languageCode == LanguageCode.IT && Utility.IsMatch(action.ActionNameIT, keyword)) ||
                                            (languageCode == LanguageCode.JP && Utility.IsMatch(action.ActionNameJP, keyword)) ||
                                            (languageCode == LanguageCode.KO && Utility.IsMatch(action.ActionNameKO, keyword)) ||
                                            (languageCode == LanguageCode.TH && Utility.IsMatch(action.ActionNameTH, keyword)) ||
                                            (languageCode == LanguageCode.VI && Utility.IsMatch(action.ActionNameVI, keyword))
                                        )
                         )
                     .ToList();
            }
            else
            {
                actionList = actionList.AsQueryable()
                                    .Select(action => action)
                                    .Where(action =>
                                                       (action.ActionTypeID == actionTypeId || actionTypeId == -1)
                                        )
                                    .ToList();
            }
            return actionList;
        }

        public List<string> GetAllSpName()
        {
            var actionList = GetLogActionList();
            return actionList.Select(action => action.SPName).ToList();
        }

        #endregion

        #region Private functions
        /// <summary>
        /// Get all log action from database and add into hashtable
        /// </summary>
        /// <returns>Hashtable</returns>
        private Hashtable GetHashLogActionData()
        {
            var hashtable = _cache.Get<Hashtable>(Constants.CacheKeyLogAction);
            if (ReferenceEquals(hashtable, null) || hashtable.Count <= 0)
            {
                /*
                 * Get all log action and add to hashtable for better performance
                 * hashkey is 
                 */

                hashtable = new Hashtable();
                var logActionList = GetLogActionList();
                if (!ReferenceEquals(logActionList, null))
                {
                    logActionList.ForEach
                        (s => hashtable.Add(s.ActionID, s));
                }

                //add logaction list as a hashtable to get a logaction with better performance
                _cache.Set<Hashtable>(Constants.CacheKeyLogAction, hashtable, TimeSpan.FromHours(1));
            }

            return hashtable;
        }

        /// <summary>
        /// Get all logaction and add to cache
        /// </summary>
        /// <returns></returns>
        private List<LogAction> GetLogActionList()
        {
            var entityList = _cache.Get<List<LogAction>>(Constants.CacheKeyLogActionList) as List<LogAction>;
            if (entityList == null)
            {
                entityList = _repository.GetAll() as List<LogAction>;

                //add to cache
                _cache.Set<List<LogAction>>(Constants.CacheKeyLogActionList, entityList, TimeSpan.FromHours(1));
            }

            return entityList;
        }
        #endregion
    }
